public class HttpServerForTest implements AutoCloseable {

    // TEST-NET-1 avoids real destinations; transport mapping sends requests only to loopback.
    public static final String PUBLIC_FIXTURE_HOST = "192.0.2.1";
    private HttpServer server;
    private ExecutorService executorService;
    private final int requestedPort;
    private final AtomicInteger forbiddenRequests = new AtomicInteger();

    public HttpServerForTest(int port) {
        this.requestedPort = port;
    }

    public synchronized void start() throws IOException {
        if (server != null) {
            return;
        }
        HttpServer candidate = HttpServer.create(new InetSocketAddress("127.0.0.1", requestedPort), 0);
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            candidate.createContext("/", this::handle);
            candidate.setExecutor(executor);
            candidate.start();
            server = candidate;
            executorService = executor;
        } catch (RuntimeException e) {
            candidate.stop(0);
            executor.shutdownNow();
            throw e;
        }
    }

    public synchronized int getPort() {
        if (server == null) {
            throw new IllegalStateException("server is not started");
        }
        return server.getAddress().getPort();
    }

    public InetSocketAddress proxyAddress() {
        return new InetSocketAddress("127.0.0.1", getPort());
    }

    public String url(String path) {
        return "http://" + PUBLIC_FIXTURE_HOST + ":" + getPort() + path;
    }

    public String localUrl(String path) {
        return "http://127.0.0.1:" + getPort() + path;
    }

    public String redirectTo(String target) throws IOException {
        return url("/redirect?url=" + URLEncoder.encode(target, StandardCharsets.UTF_8.name()));
    }

    public String[] forbiddenUrls() {
        String suffix = ":" + getPort() + "/forbidden";
        return new String[]{
                "http://127.0.0.1" + suffix,
                "http://10.0.0.1" + suffix,
                "http://0.0.0.0" + suffix,
                "http://0" + suffix,
                "http://[::1]" + suffix,
                "http://[::]" + suffix
        };
    }

    public int getForbiddenRequestCount() {
        return forbiddenRequests.get();
    }

    public synchronized void stop() {
        if (server != null) {
            server.stop(0);
            server = null;
        }
        if (executorService != null) {
            executorService.shutdownNow();
            executorService = null;
        }
    }

    @Override
    public void close() {
        stop();
    }

    private void handle(HttpExchange exchange) throws IOException {
        try {
            String path = exchange.getRequestURI().getPath();
            exchange.getResponseHeaders().set("X-Test-Host", exchange.getRequestHeaders().getFirst("Host"));
            if ("/redirect".equals(path)) {
                String query = exchange.getRequestURI().getRawQuery();
                if (query == null || !query.startsWith("url=")) {
                    exchange.sendResponseHeaders(400, -1);
                    return;
                }
                exchange.getResponseHeaders().set("Location", URLDecoder.decode(query.substring(4), StandardCharsets.UTF_8.name()));
                byte[] response = "redirect".getBytes(StandardCharsets.UTF_8);
                exchange.sendResponseHeaders(302, response.length);
                try (OutputStream body = exchange.getResponseBody()) {
                    body.write(response);
                }
                return;
            }
            int status = 200;
            if ("/forbidden".equals(path)) {
                forbiddenRequests.incrementAndGet();
                status = 500;
            }
            byte[] response = path.getBytes(StandardCharsets.UTF_8);
            exchange.sendResponseHeaders(status, response.length);
            try (OutputStream body = exchange.getResponseBody()) {
                body.write(response);
            }
        } finally {
            exchange.close();
        }
    }
}

package com.alibaba.seckit.xxe;

import com.alibaba.seckit.SecurityUtil;
import org.dom4j.Document;
import org.dom4j.io.SAXReader;
import org.jdom2.input.SAXBuilder;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.xml.sax.helpers.DefaultHandler;
import org.xml.sax.helpers.XMLReaderFactory;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamReader;
import javax.xml.transform.Source;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamResult;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.validation.Validator;
import java.io.InputStream;
import java.io.StringWriter;

public class XmlParsers {
    public static interface XmlParser {
        String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception;
    }

    public static class Dom4jSaxReader implements XmlParser {
        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            SAXReader reader;
            if (xInclude) {
                SAXParserFactory spf = SAXParserFactory.newInstance();
                spf.setNamespaceAware(true);
                spf.setXIncludeAware(true);

                SAXParser parser = spf.newSAXParser();
                reader = new SAXReader( parser.getXMLReader());
            } else {
                reader = new SAXReader();
            }
            if (secure) {
                reader = SecurityUtil.withXxeProtection(reader);
            }
            Document doc = reader.read(inputStream);
            return (String) doc.getRootElement().getData();
        }
    }

    public static class DocumentBuilderFactoryParser implements XmlParser {
        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            if (xInclude) {
                dbf.setNamespaceAware(true);
                dbf.setXIncludeAware(true);
            }

            if (secure) {
                dbf = SecurityUtil.withXxeProtection(dbf);
            }
            DocumentBuilder builder = dbf.newDocumentBuilder();
            org.w3c.dom.Document doc = builder.parse(inputStream);
            return doc.getDocumentElement().getTextContent();
        }
    }

    public static class RootTextHandler extends DefaultHandler {
        private String rootText;

        @Override
        public void characters(char[] ch, int start, int length) throws SAXException {
            rootText += new String(ch, start, length);
        }

        public String getRootText() {
            return rootText;
        }
    }

    public static class SaxParserFactoryParser implements XmlParser {
        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            SAXParserFactory spf = SAXParserFactory.newInstance();
            if (xInclude) {
                spf.setXIncludeAware(true);
                spf.setNamespaceAware(true);
            }
            if (secure) {
                spf = SecurityUtil.withXxeProtection(spf);
            }
            SAXParser parser = spf.newSAXParser();
            RootTextHandler handler = new RootTextHandler();
            parser.parse(inputStream, handler);
            return handler.getRootText();
        }
    }

    public static class XMLInputFactoryParser implements XmlParser {

        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            XMLInputFactory factory = XMLInputFactory.newInstance();

            if (secure) {
                factory = SecurityUtil.withXxeProtection(factory);
            }
            XMLStreamReader reader = factory.createXMLStreamReader(inputStream);
            StringBuilder rootText = new StringBuilder();

            while (reader.hasNext()) {
                int point = reader.next();
                switch (point) {
                    case XMLStreamReader.CHARACTERS:
                        rootText.append(reader.getText());
                }
            }
            return rootText.toString();
        }


    }

    public static class SaxBuilderParser implements XmlParser {
        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            SAXBuilder saxBuilder = new SAXBuilder();
            if (secure) {
                saxBuilder = SecurityUtil.withXxeProtection(saxBuilder);
            }
            org.jdom2.Document doc = saxBuilder.build(inputStream);
            return doc.getRootElement().getText();
        }
    }

    public static class XmlReaderParser implements XmlParser {

        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            XMLReader reader = XMLReaderFactory.createXMLReader();
            if (secure) {
                reader = SecurityUtil.withXxeProtection(reader);
            }
            RootTextHandler handler = new RootTextHandler();
            reader.setContentHandler(handler);
            reader.parse(new InputSource(inputStream));
            return handler.getRootText();
        }
    }

    public static class ValidatorParser implements XmlParser {

        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            SchemaFactory factory = SchemaFactory.newInstance("http://www.w3.org/2001/XMLSchema");
            Schema schema = factory.newSchema();
            Validator validator = schema.newValidator();
            if (secure) {
                validator = SecurityUtil.withXxeProtection(validator);
            }
            Source s = new StreamSource(inputStream);
            validator.validate(s);
            return "root:Doe:Answer";
        }
    }

    public static class SchemaFactoryParser implements XmlParser {

        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            SchemaFactory factory = SchemaFactory.newInstance("http://www.w3.org/2001/XMLSchema");
            if (secure) {
                factory = SecurityUtil.withXxeProtection(factory);
            }
            Schema schema = factory.newSchema(new StreamSource(inputStream));
            Validator validator = schema.newValidator();
            Source s = new StreamSource(this.getClass().getResourceAsStream("/xxe/simple.xml"));
            validator.validate(s);
            return "root:Doe:Answer";
        }
    }

    public static class TransformerFactoryParser implements XmlParser {

        @Override
        public String parse(InputStream inputStream, boolean xInclude, boolean secure) throws Exception {
            TransformerFactory factory = TransformerFactory.newInstance();
            if (secure) {
                factory = SecurityUtil.withXxeProtection(factory);
            }
            Transformer transformer = factory.newTransformer();
            StringWriter sw = new StringWriter();
            transformer.transform(new StreamSource(inputStream), new StreamResult(sw));
            return sw.toString();
        }
    }

}

package com.alibaba.seckit.cli;

import com.alibaba.seckit.SecurityUtil;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

public class CliToolTest {

    @Test
    public void testNullAndEmpty() {
        assertNull(SecurityUtil.trimCmd(null));
        assertEquals("", SecurityUtil.trimCmd(""));
        assertEquals("", SecurityUtil.trimCmd(" ;&|$()`\"'\\/\t\n\r\0"));
    }

    @Test
    public void testAsciiAllowlist() {
        String allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.,";
        assertEquals(allowed, SecurityUtil.trimCmd(allowed));
        assertEquals("aA09_-.,z", SecurityUtil.trimCmd(" aA09_-.,z "));
        assertEquals("Aa123.", SecurityUtil.trimCmd("Aa1&&$@^%!()2\"3#.\0"));
    }

    @Test
    public void testChineseCharactersArePreserved() {
        assertEquals("中文参数,测试文件.txt", SecurityUtil.trimCmd("中文参数,测试文件.txt"));
        assertEquals("abc中文_-.,123", SecurityUtil.trimCmd("abc 中文_-.,123"));
        assertEquals("测试.txt", SecurityUtil.trimCmd("'测试.txt'"));
    }

    @Test
    public void testChineseRangeBoundariesAndUnsupportedUnicode() {
        assertEquals("\u4e00\u9fbb", SecurityUtil.trimCmd("\u4dff\u4e00\u9fbb\u9fbc\u9fff"));
        assertEquals("中文", SecurityUtil.trimCmd("中の文あいうéＡ１\ud83d\ude00"));
        assertEquals("ab", SecurityUtil.trimCmd("a\ud800\udc00\ud800\udc00b"));
        assertEquals("ab", SecurityUtil.trimCmd("a\ud800b\udc00"));
    }

    @Test
    public void testControlCharactersAndSeparatorsAreRemoved() {
        assertEquals("abcdef", SecurityUtil.trimCmd("a\0b\tc\nd\re\u001af"));
        assertEquals("中文abcdef", SecurityUtil.trimCmd("中文 a;b&c|d$e`f`"));
        assertEquals("abcdef", SecurityUtil.trimCmd("a/b\\c:d=e+f"));
        assertEquals("ab", SecurityUtil.trimCmd("a\u00a0\u3000\u200bb"));
    }

    @Test
    public void testConsecutiveHyphensAndCommasFollowCommandAllowlist() {
        assertEquals("--name中文", SecurityUtil.trimCmd("--name=中文"));
        assertEquals("a--b,,c", SecurityUtil.trimCmd("a--b,,c"));
        assertEquals("arg1,arg2中文", SecurityUtil.trimCmd("arg1, arg2中文"));
    }

    @Test
    public void testEveryCharacterMatchesTheSpecifiedAllowlist() {
        CLITool tool = new CLIToolImpl();
        for (int value = Character.MIN_VALUE; value <= Character.MAX_VALUE; value++) {
            char c = (char) value;
            boolean allowed = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                    || (c >= '0' && c <= '9') || c == '_' || c == '-' || c == ',' || c == '.'
                    || (c >= 0x4e00 && c <= 0x9fbb);
            String input = String.valueOf(c);
            assertEquals("character U+" + Integer.toHexString(value), allowed ? input : "", tool.filter(input));
        }
    }

    @Test
    public void testOutputIsStableUnderRepeatedFiltering() {
        String input = "'中文文件.txt';$(echo other) --flag,arg";
        String filtered = SecurityUtil.trimCmd(input);
        assertEquals(filtered, SecurityUtil.trimCmd(filtered));
        assertFalse(filtered.contains(" "));
        assertFalse(filtered.contains(";"));
        assertEquals(new CLIToolImpl().filter(input), filtered);
    }
}

package com.alibaba.seckit.util;

import com.alibaba.seckit.SecurityUtil;
import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static org.junit.Assert.*;

/**
 * @author mingyi
  */
public class EscapeStringEncoderTest {

    @Test
    public void testDefaultEncodeAndDecode() {
        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder();

        String original = "hello%world+test";
        String encoded = escapeStringEncoder.encode(original);
        assertEquals("hello%00world%01test", encoded);

        String decoded = escapeStringEncoder.decode(encoded);
        assertEquals(original, decoded);
    }

    @Test
    public void testEncodeAndDecodeWithAllSpecialChars() {
        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder();

        String original = "%+ &?=";
        String encoded = escapeStringEncoder.encode(original);
        assertEquals("%00%01%02%03%04%05", encoded);

        String decoded = escapeStringEncoder.decode(encoded);
        assertEquals(original, decoded);
    }

    @Test
    public void testEncodeAndDecodeWithNoSpecialChars() {
        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder();

        String original = "hello world";
        String encoded = escapeStringEncoder.encode(original);
        assertEquals("hello%02world", encoded);

        String decoded = escapeStringEncoder.decode(encoded);
        assertEquals(original, decoded);
    }

    @Test
    public void testEncodeAndDecodeEmptyAndNull() {
        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder();

        String encoded = escapeStringEncoder.encode("");
        assertEquals("", encoded);

        String decoded = escapeStringEncoder.decode("");
        assertEquals("", decoded);

        assertNull(escapeStringEncoder.encode(null));
        assertNull(escapeStringEncoder.decode(null));
    }

    @Test
    public void testCustomEscapeString() {
        char escapeChar = '#';
        char[] encodeChars = {'@', '#', '$'};
        char[] availableChars = {'a', 'b', 'c'};

        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder(escapeChar, encodeChars, availableChars);

        String original = "test@string#with$special@chars";
        String encoded = escapeStringEncoder.encode(original);
        assertEquals("test#aastring#abwith#acspecial#aachars", encoded);

        String decoded = escapeStringEncoder.decode(encoded);
        assertEquals(original, decoded);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCustomEscapeStringWithoutEncodeEscapeChar() {
        char escapeChar = '#';
        char[] encodeChars = {'@', '$'};
        char[] availableChars = {'a', 'b', 'c'};
        new EscapeStringEncoder(escapeChar, encodeChars, availableChars);
    }

    @Test
    public void testWithDuplicateChars() {
        char escapeChar = '%';
        char[] encodeChars = {'%', '+'};
        char[] availableChars = {'0', '1', '%'};

        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder(escapeChar, encodeChars, availableChars);
        String original = "test%%with%01%%+duplicate%1%%+1chars";
        String encoded = escapeStringEncoder.encode(original);
        assertEquals("test%00%00with%0001%00%00%01duplicate%001%00%00%011chars", encoded);

        String decoded = escapeStringEncoder.decode(encoded);
        assertEquals(original, decoded);
    }

    @Test
    public void testDuplicateEncodeCharKeepsLastMapping() {
        EscapeStringEncoder escapeStringEncoder = new EscapeStringEncoder('%', new char[]{'%', '%'}, new char[]{'0', '1'});
        assertEquals("%01", escapeStringEncoder.encode("%"));
        assertEquals("%", escapeStringEncoder.decode("%01"));
        assertEquals("%00", escapeStringEncoder.decode("%00"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCollidingEncodedValuesAreRejected() {
        new EscapeStringEncoder('%', new char[]{'%', '+'}, new char[]{'0', '0'});
    }

    @Test
    public void testMainClassesDoNotReferenceUndeclaredGuava() throws Exception {
        // Guava is only a transitive provided dependency, so library users do not have it at runtime.
        Path classes = Paths.get(SecurityUtil.class.getProtectionDomain().getCodeSource().getLocation().toURI());
        List<Path> offenders;
        try (Stream<Path> files = Files.walk(classes)) {
            offenders = files.filter(path -> path.toString().endsWith(".class"))
                    .filter(EscapeStringEncoderTest::referencesGuava)
                    .collect(Collectors.toList());
        }
        assertTrue("main classes reference Guava: " + offenders, offenders.isEmpty());
    }

    private static boolean referencesGuava(Path classFile) {
        try {
            return new String(Files.readAllBytes(classFile), StandardCharsets.ISO_8859_1).contains("com/google/common/");
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }
}

package com.alibaba.seckit.xxe;


import com.alibaba.seckit.util.HttpServerForTest;
import org.apache.commons.lang3.SystemUtils;
import org.junit.AfterClass;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;


/*
XXE Payload: https://github.com/swisskyrepo/PayloadsAllTheThings/tree/master/XXE%20Injection#exploiting-blind-xxe-to-exfiltrate-data-out-of-band
不同框架可利用的XXE payload： https://semgrep.dev/docs/cheat-sheets/java-xxe/#3e-saxreader
*/
public class XxeToolTest {


    private static final Map<String, String> xmlContentMap = new HashMap<>();
    private static final HttpServerForTest server = new HttpServerForTest(0);

    @BeforeClass
    public static void before() throws IOException {
        server.start();
        xmlContentMap.put("file.xml", "root:");
        xmlContentMap.put("simple.xml", "Doe");
        xmlContentMap.put("ssrf.xml", "Answer");
    }

    @AfterClass
    public static void after() {
        server.close();
    }

    @Test
    public void testXXE() {
        Class<?>[] parserClasses = new Class[]{
                XmlParsers.Dom4jSaxReader.class,
                XmlParsers.DocumentBuilderFactoryParser.class,
                XmlParsers.SaxParserFactoryParser.class,
                XmlParsers.XMLInputFactoryParser.class,
                XmlParsers.SaxBuilderParser.class,
                XmlParsers.XmlReaderParser.class,
        };

        for (Class<?> parserClass : parserClasses) {
            for (String f : xmlContentMap.keySet()) {
                assertResultOrException(parserClass, f, xmlContentMap.get(f), false, false);
                assertResultOrException(parserClass, f, null, false, true);
            }
        }

        // test xinclude
        Class<?>[] xIncludeClasses = new Class[]{
                XmlParsers.Dom4jSaxReader.class,
                XmlParsers.DocumentBuilderFactoryParser.class,
                XmlParsers.SaxParserFactoryParser.class,
        };

        for (Class<?> parserClass : xIncludeClasses) {
            assertResultOrException(parserClass, "xinclude.xml", "root:", true, false);
            assertResultNotContains(parserClass, "xinclude.xml", "root:", true, true);
        }

        // Validator, TransformerFactory
        parserClasses = new Class[]{
                XmlParsers.ValidatorParser.class,
                XmlParsers.TransformerFactoryParser.class,

        };
        for (Class<?> parserClass : parserClasses) {
            for (String f : new String[] {"file.xml", "ssrf.xml"}) {
                assertResultOrException(parserClass, f, "", false, false);
                assertResultOrException(parserClass, f, null, false, true);
            }
        }

        // test SchemaFactory
        try {
            getXmlParseResult(XmlParsers.SchemaFactoryParser.class, "file.xml", false, false);
        } catch (Exception e) {
            if(SystemUtils.IS_OS_LINUX) {
                Assert.assertTrue(e.getMessage(), e.getMessage().contains("root:x:0:0"));
            } else {
                Assert.assertTrue(e.getMessage(), e.getMessage().contains("User Database") || e.getMessage().contains("Saw '##'"));
            }
        }
        try {
            getXmlParseResult(XmlParsers.SchemaFactoryParser.class, "file.xml", false, true);
            Assert.fail();
        } catch (Exception e) {
            if (e instanceof RuntimeException) {
                throw new RuntimeException(e);
            }
        }
        try {
            getXmlParseResult(XmlParsers.SchemaFactoryParser.class, "ssrf.xml", false, false);
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("Answer"));
        }
        try {
            getXmlParseResult(XmlParsers.SchemaFactoryParser.class, "ssrf.xml", false, true);
            Assert.fail();
        } catch (Exception e) {
            if (e instanceof RuntimeException) {
                throw new RuntimeException(e);
            }
        }

    }


    public String getXmlParseResult(Class<?> parserClass, String fileName, boolean xInclude, boolean secure) throws Exception {
        try (InputStream resource = getClass().getResourceAsStream("/xxe/" + fileName)) {
            XmlParsers.XmlParser parser = (XmlParsers.XmlParser) parserClass.getDeclaredConstructor().newInstance();
            if (!"ssrf.xml".equals(fileName)) {
                return parser.parse(resource, xInclude, secure);
            }
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            byte[] buffer = new byte[2048];
            int count;
            while ((count = resource.read(buffer)) != -1) {
                bytes.write(buffer, 0, count);
            }
            String xml = new String(bytes.toByteArray(), StandardCharsets.UTF_8)
                    .replace("__XXE_ENTITY_URL__", server.localUrl("/Answer"));
            try (InputStream input = new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8))) {
                return parser.parse(input, xInclude, secure);
            }
        }
    }

    public void assertResultOrException(Class<?> parserClass, String fileName, String content, boolean xInclude, boolean secure) {
        try {
            String result = getXmlParseResult(parserClass, fileName, xInclude, secure);
            if (content == null) {
                Assert.fail(String.format("test for %s should throw an exception, actual: %s.", parserClass.getName(), result));
            } else {
                Assert.assertTrue(
                        String.format(
                                "test for %s should return a string contains:%s, but actual: %s",
                                parserClass.getName(),
                                content,
                                result),
                        result.contains(content));
            }
        } catch (Exception e) {
            if (e instanceof RuntimeException || content != null) {
                e.printStackTrace();
                Assert.fail();
            }
        }
    }

    public void assertResultNotContains(Class<?> parserClass, String fileName, String content, boolean xInclude, boolean secure) {
        try {
            String result = getXmlParseResult(parserClass, fileName, xInclude, secure);
            Assert.assertFalse(
                    String.format(
                            "test for %s should return not a string contains:%s, but actual: %s",
                            parserClass.getName(),
                            content,
                            result),
                    result.contains(content));

        } catch (Exception e) {
            e.printStackTrace();
            Assert.fail();
        }
    }
}

package com.alibaba.seckit.jdbc;

import com.alibaba.seckit.SecurityUtil;
import com.alibaba.seckit.jdbc.parser.SnowFlakeParser;
import org.junit.Test;

import java.net.URI;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class SnowFlakeParserTest {

    private static final String PREFIX = "jdbc:snowflake://";
    private static final String HOST = "account.snowflakecomputing.com";

    @Test
    public void testInterfaceParseUsesSnowflakeScheme() throws Exception {
        String url = PREFIX + HOST + "?user=u";
        UrlParser parser = new SnowFlakeParser(url);
        parser.parse();

        SnowFlakeParser snowflake = (SnowFlakeParser) parser;
        assertEquals(url, parser.getInitialUrl());
        assertEquals("snowflake", snowflake.getScheme());
        assertEquals(HOST, snowflake.getHost());
        assertEquals(-1, snowflake.getPort());
        assertEquals(Collections.singletonMap("user", "u"), parser.getProperties());
        assertTrue(parser.toString().startsWith(PREFIX + HOST + "/?"));
        assertRoundTrip(snowflake);
    }

    @Test
    public void testSecurityUtilReproFiltersWithoutDoublingPrefix() throws Exception {
        String filtered = SecurityUtil.filterJdbcConnectionSource(
                PREFIX + HOST + "/?user=u&password=[REDACTED]");

        URI uri = new URI(filtered.substring("jdbc:".length()));
        assertEquals("snowflake", uri.getScheme());
        assertEquals(HOST, uri.getHost());
        assertEquals(-1, uri.getPort());
        assertEquals("/", uri.getPath());
        assertTrue(filtered.startsWith(PREFIX + HOST + "/?"));

        Map<String, String> expected = new HashMap<>();
        expected.put("user", "u");
        expected.put("password", "p");
        SnowFlakeParser parser = parse(filtered);
        assertEquals(expected, parser.getProperties());
        assertRoundTrip(parser);
    }

    @Test
    public void testSlashQueryAndPortVariants() throws Exception {
        String[] endings = {"", "/", "?", "/?", "?user=u", "/?user=u"};
        for (int port : new int[]{-1, 0, 443, 65535}) {
            String authority = HOST + (port < 0 ? "" : ":" + port);
            for (String ending : endings) {
                String url = PREFIX + authority + ending;
                SnowFlakeParser parser = parse(url);
                assertEquals(url, "snowflake", parser.getScheme());
                assertEquals(url, HOST, parser.getHost());
                assertEquals(url, port, parser.getPort());
                assertNull(parser.getDatabase());
                Map<String, String> expected = ending.endsWith("user=u")
                        ? Collections.singletonMap("user", "u") : Collections.emptyMap();
                assertEquals(url, expected, parser.getProperties());
                assertTrue(parser.toString().startsWith(PREFIX + authority + "/"));
                assertRoundTrip(parser);

                SnowFlakeParser filtered = parse(SecurityUtil.filterJdbcConnectionSource(url));
                assertEquals(HOST, filtered.getHost());
                assertEquals(port, filtered.getPort());
                assertEquals(expected, filtered.getProperties());
                assertRoundTrip(filtered);
            }
        }
    }

    @Test
    public void testMixedCasePrefixIsCanonicalized() throws Exception {
        String url = "JdBc:SnOwFlAkE://Account.snowflakecomputing.com/?USER=u&FakeParam=evil";
        SnowFlakeParser parser = parse(url);
        assertEquals("snowflake", parser.getScheme());
        assertEquals("Account.snowflakecomputing.com", parser.getHost());
        assertRoundTrip(parser);

        String filtered = SecurityUtil.filterJdbcConnectionSource(url);
        assertTrue(filtered.startsWith(PREFIX + "Account.snowflakecomputing.com/?"));
        parser = parse(filtered);
        assertEquals(Collections.singletonMap("USER", "u"), parser.getProperties());
        assertRoundTrip(parser);
    }

    @Test
    public void testUnderscoreAndIpv6Hosts() throws Exception {
        String[] hosts = {"account_name.snowflakecomputing.com", "[::1]", "[2001:db8::1]"};
        for (String host : hosts) {
            for (int port : new int[]{-1, 443}) {
                String authority = host + (port < 0 ? "" : ":" + port);
                String url = PREFIX + authority + "?allowUnderscoresInHost=true&fakeParam=evil";
                SnowFlakeParser parser = parse(url);
                assertEquals(host, parser.getHost());
                assertEquals(port, parser.getPort());
                assertRoundTrip(parser);

                String filtered = SecurityUtil.filterJdbcConnectionSource(url);
                assertTrue(filtered.startsWith(PREFIX + authority + "/?"));
                parser = parse(filtered);
                assertEquals(host, parser.getHost());
                assertEquals(port, parser.getPort());
                assertEquals(Collections.singletonMap("allowUnderscoresInHost", "true"), parser.getProperties());
                assertRoundTrip(parser);
            }
        }
    }

    @Test
    public void testUtf8DecodingFirstEqualsAndExistingValuePolicy() throws Exception {
        String url = PREFIX + HOST + "/?%75ser=用户&%70assword=p%26x=y%2Bz+space=="
                + "&role=分析&schema=%E5%88%86%E6%9E%90&application=client%2Dapp"
                + "&warehouse=wh%5F1&db=&fakeParam=evil&%E5%8F%82%E6%95%B0=%E5%80%BC&ignored";
        Map<String, String> allowed = new HashMap<>();
        allowed.put("user", "用户");
        allowed.put("password", "p&x=y+z space==");
        allowed.put("application", "client-app");
        allowed.put("warehouse", "wh_1");
        allowed.put("db", "");

        Map<String, String> parsed = new HashMap<>(allowed);
        parsed.put("role", "分析");
        parsed.put("schema", "分析");
        parsed.put("fakeParam", "evil");
        parsed.put("参数", "值");
        SnowFlakeParser parser = parse(url);
        assertEquals(parsed, parser.getProperties());
        assertRoundTrip(parser);

        // Credentials bypass value restrictions; other accepted keys still use the ASCII value policy.
        String filtered = SecurityUtil.filterJdbcConnectionSource(url);
        parser = parse(filtered);
        assertEquals(allowed, parser.getProperties());
        assertRoundTrip(parser);
        assertEquals(allowed, parse(SecurityUtil.filterJdbcConnectionSource(filtered)).getProperties());
    }

    @Test
    public void testIntendedNestedHttpAndHttpsSchemes() throws Exception {
        for (String scheme : new String[]{"http", "https"}) {
            for (int port : new int[]{-1, 8443}) {
                String authority = HOST + (port < 0 ? "" : ":" + port);
                String url = PREFIX + scheme + "://" + authority + "?user=u&fakeParam=evil";
                SnowFlakeParser parser = parse(url);
                assertEquals(scheme, parser.getScheme());
                assertEquals(HOST, parser.getHost());
                assertEquals(port, parser.getPort());
                assertTrue(parser.toString().startsWith(PREFIX + scheme + "://" + authority + "/?"));
                assertRoundTrip(parser);

                String filtered = SecurityUtil.filterJdbcConnectionSource(url);
                assertTrue(filtered.startsWith(PREFIX + scheme + "://" + authority + "/?"));
                parser = parse(filtered);
                assertEquals(scheme, parser.getScheme());
                assertEquals(HOST, parser.getHost());
                assertEquals(port, parser.getPort());
                assertEquals(Collections.singletonMap("user", "u"), parser.getProperties());
                assertRoundTrip(parser);
            }
        }
    }

    @Test
    public void testMalformedUrlsAndUnsupportedSchemesAreRejected() {
        String[] invalid = {
                null, "", "jdbc:snowflake:", "jdbc:snowflake:/" + HOST,
                "jdbc:snowflake2://" + HOST, "snowflake://" + HOST, "http://" + HOST,
                PREFIX, PREFIX + "/", PREFIX + "?user=u", PREFIX + "/?user=u",
                PREFIX + "host name", PREFIX + "user@" + HOST,
                PREFIX + "[::1", PREFIX + HOST + ":abc", PREFIX + HOST + ":-1",
                PREFIX + HOST + ":65536", PREFIX + HOST + ":999999999999",
                PREFIX + HOST + "/database", PREFIX + HOST + "//", PREFIX + HOST + "/%64atabase",
                PREFIX + "http://", PREFIX + "https://?user=u",
                PREFIX + "https://" + HOST + "/database",
                PREFIX + "ftp://" + HOST, PREFIX + "snowflake://" + HOST
        };
        for (String url : invalid) {
            assertThrows(String.valueOf(url), JdbcURLUnsafeException.class, () -> parse(url));
        }
    }

    @Test
    public void testMalformedQueryEncodingThrowsCheckedUnsafeException() {
        for (String query : new String[]{"user=%", "password=%2", "%GG=u", "user=%XY"}) {
            String url = PREFIX + HOST + "/?" + query;
            assertThrows(url, JdbcURLUnsafeException.class, () -> parse(url));
            assertThrows(url, JdbcURLUnsafeException.class, () -> SecurityUtil.filterJdbcConnectionSource(url));
        }
    }

    private static SnowFlakeParser parse(String url) throws JdbcURLException {
        SnowFlakeParser parser = new SnowFlakeParser(url);
        UrlParser urlParser = parser;
        urlParser.parse();
        return parser;
    }

    private static void assertRoundTrip(SnowFlakeParser parser) throws JdbcURLException {
        SnowFlakeParser reparsed = parse(parser.toString());
        assertEquals(parser.getScheme(), reparsed.getScheme());
        assertEquals(parser.getHost(), reparsed.getHost());
        assertEquals(parser.getPort(), reparsed.getPort());
        assertEquals(parser.getDatabase(), reparsed.getDatabase());
        assertEquals(parser.getProperties(), reparsed.getProperties());
    }
}

package com.alibaba.seckit.deserialize;

import com.alibaba.seckit.SecurityUtil;
import com.alibaba.seckit.deserialize.testcase.Basic;
import com.alibaba.seckit.deserialize.testcase.InnerClass;
import com.alibaba.seckit.deserialize.testcase.Nested;
import com.alibaba.seckit.deserialize.testcase.SubPackage;
import lombok.AllArgsConstructor;
import lombok.Getter;
import org.junit.Assert;
import org.junit.Test;


import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InvalidClassException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Properties;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class DeserializeToolTest {

    @AllArgsConstructor
    @Getter
    static class TestCase {
        Class<?> cls;
        String[] allowedPatterns;
        Class<?>[] allowedClasses;
        boolean shouldBlock;
    }

    @Test
    public void testDeserialize() throws IOException, ReflectiveOperationException {
        TestCase[] testCases = new TestCase[]{
                new TestCase(Basic.class, null, null, true),
                new TestCase(Basic.class, new String[]{Basic.class.getName()}, null, false),
                new TestCase(Basic.class, null, new Class[]{Basic.class}, false),
                new TestCase(Nested.class, null, new Class[]{Nested.class}, false),
                new TestCase(Nested.class, new String[]{Nested.class.getName()}, new Class[]{}, true),
                new TestCase(Nested.class, new String[]{"com.alibaba.seckit.deserialize.testcase.*"}, null, false),
                new TestCase(SubPackage.class, new String[]{"com.alibaba.seckit.deserialize.testcase.*"}, null, true),
                new TestCase(SubPackage.class, new String[]{"com.alibaba.seckit.deserialize.testcase.**"}, null, false),
                new TestCase(SubPackage.class, new String[]{}, new Class[]{SubPackage.class}, false),
                new TestCase(SubPackage.class, new String[]{"com.alibaba.seckit.deserialize.testcase.*", "com.alibaba.seckit.deserialize.testcase.allowed.*"}, null, true),
                new TestCase(SubPackage.class, new String[]{"com.alibaba.seckit.deserialize.testcase.*", "com.alibaba.seckit.deserialize.testcase.allowed.*", "com.alibaba.seckit.deserialize.testcase.blocked.*"}, null, false),
                new TestCase(InnerClass.class, new String[]{}, new Class[]{InnerClass.class}, false),
                new TestCase(InnerClass.class, new String[]{"com.alibaba.seckit.deserialize.testcase.*"}, null, false),
        };

        for (TestCase testCase : testCases) {
            assertDeserialize(testCase.cls, testCase.allowedPatterns, testCase.allowedClasses, testCase.shouldBlock);
        }
    }

    private void assertDeserialize(Class<?> cls, String[] allowedPatterns, Class<?>[] allowedClasses, boolean shouldBlock)
            throws IOException, ReflectiveOperationException {
        Object obj = cls.getDeclaredConstructor().newInstance();
        byte[] serialized;
        try (ByteArrayOutputStream bytes = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bytes)) {
            oos.writeObject(obj);
            oos.flush();
            serialized = bytes.toByteArray();
        }
        try (ByteArrayInputStream bytes = new ByteArrayInputStream(serialized);
             ObjectInputStream ois = newObjectInputStream(bytes, allowedPatterns, allowedClasses)) {
            try {
                ois.readObject();
                if (shouldBlock) {
                    Assert.fail("test case failed: " + cls.getName() + "#" + Arrays.toString(allowedPatterns) + "#" + Arrays.toString(allowedClasses));
                }
            } catch (InvalidClassException e) {
                if (!shouldBlock) {
                    throw e;
                }
            }
        }
    }

    private ObjectInputStream newObjectInputStream(ByteArrayInputStream bytes, String[] allowedPatterns, Class<?>[] allowedClasses)
            throws IOException {
        if (allowedPatterns != null && allowedClasses != null) {
            return SecurityUtil.newObjectInputStream(bytes, allowedPatterns, allowedClasses);
        } else if (allowedPatterns != null) {
            return SecurityUtil.newObjectInputStream(bytes, allowedPatterns);
        } else if (allowedClasses != null) {
            return SecurityUtil.newObjectInputStream(bytes, allowedClasses);
        } else {
            return SecurityUtil.newObjectInputStream(bytes);
        }
    }

    @Test
    public void testDefaultFilterIsCached() throws ReflectiveOperationException {
        DeserializeToolImpl tool = new DeserializeToolImpl();
        // The return type moves from sun.misc to java.io in the Java 9 overlay.
        Method factory = DeserializeToolImpl.class.getMethod("newObjectInputFilter", String[].class, Class[].class);
        Object defaultFilter = factory.invoke(tool, new Object[]{null, null});
        Assert.assertNotNull(defaultFilter);
        Assert.assertSame(defaultFilter, factory.invoke(tool, new Object[]{null, null}));
        Assert.assertSame(defaultFilter, factory.invoke(tool, new Object[]{new String[0], new Class<?>[0]}));
        Assert.assertSame(defaultFilter, factory.invoke(tool, new Object[]{null, new Class<?>[0]}));
        Assert.assertSame(defaultFilter, factory.invoke(tool, new Object[]{new String[0], null}));
        Assert.assertSame(defaultFilter, factory.invoke(new DeserializeToolImpl(), new Object[]{null, null}));
    }

    @Test
    public void testOnlyPersistentInstanceFieldsAreAllowed() throws IOException, ClassNotFoundException {
        Set<String> names = new HashSet<>(Arrays.asList(
                DeserializeUtils.generateFilterPattern(null, new Class<?>[]{PersistentModel.class}).split(";")));
        Assert.assertTrue(names.contains(PersistentValue.class.getName()));
        Assert.assertFalse(names.contains(StaticOnly.class.getName()));
        Assert.assertFalse(names.contains(TransientOnly.class.getName()));
        PersistentModel restored = (PersistentModel) roundTrip(new PersistentModel(), PersistentModel.class);
        Assert.assertEquals("persistent", restored.value.text);
        Assert.assertNull(restored.temporary);
    }

    @Test
    public void testDefaultAllowlistDoesNotReachReflectionInfrastructure() {
        Set<String> names = new HashSet<>(Arrays.asList(DeserializeUtils.generateFilterPattern(null, null).split(";")));
        Assert.assertFalse(names.contains("java.lang.Class"));
        Assert.assertFalse(names.contains("java.lang.ClassLoader"));
        Assert.assertFalse(names.contains("java.lang.reflect.Method"));
        Assert.assertFalse(names.contains("sun.misc.Unsafe"));
        Assert.assertTrue(names.contains("java.util.Hashtable"));
    }

    @Test
    public void testRecursiveFieldsAndArraysTerminate() {
        Set<String> names = new HashSet<>(Arrays.asList(
                DeserializeUtils.generateFilterPattern(null, new Class<?>[]{RecursiveModel.class}).split(";")));
        Assert.assertTrue(names.contains(RecursiveModel.class.getName()));
        Assert.assertTrue(names.contains(PersistentValue.class.getName()));
        Assert.assertFalse(names.contains(TransientOnly.class.getName()));
    }

    @Test
    public void testCustomSerializationNeedsExplicitExtraClasses() throws IOException, ClassNotFoundException {
        Set<String> names = new HashSet<>(Arrays.asList(
                DeserializeUtils.generateFilterPattern(null, new Class<?>[]{CustomSerializedModel.class}).split(";")));
        Assert.assertFalse(names.contains(TransientOnly.class.getName()));
        try {
            roundTrip(new CustomSerializedModel(), CustomSerializedModel.class);
            Assert.fail("a transient type written by custom serialization must be explicitly allowed");
        } catch (InvalidClassException expected) {
        }
        CustomSerializedModel restored = (CustomSerializedModel) roundTrip(
                new CustomSerializedModel(), CustomSerializedModel.class, TransientOnly.class);
        Assert.assertEquals("custom", restored.value.text);
    }

    @Test
    public void testDefaultContainerSerialization() throws IOException, ClassNotFoundException {
        Properties properties = new Properties();
        properties.setProperty("key", "value");
        Assert.assertEquals(properties, roundTrip(properties));
        ConcurrentHashMap<String, String> concurrent = new ConcurrentHashMap<>();
        concurrent.put("key", "value");
        Assert.assertEquals(concurrent, roundTrip(concurrent));
        Assert.assertArrayEquals(new Object[]{"value", 42}, (Object[]) roundTrip(new Object[]{"value", 42}));
        try {
            roundTrip(new Object[]{new TransientOnly()});
            Assert.fail("Object[] storage must not allow unapproved contained classes");
        } catch (InvalidClassException expected) {
        }
    }

    private Object roundTrip(Serializable value, Class<?>... allowedClasses) throws IOException, ClassNotFoundException {
        byte[] serialized;
        try (ByteArrayOutputStream bytes = new ByteArrayOutputStream();
             ObjectOutputStream output = new ObjectOutputStream(bytes)) {
            output.writeObject(value);
            output.flush();
            serialized = bytes.toByteArray();
        }
        try (ObjectInputStream input = SecurityUtil.newObjectInputStream(new ByteArrayInputStream(serialized), allowedClasses)) {
            return input.readObject();
        }
    }

    private static class PersistentModel implements Serializable {
        private static final long serialVersionUID = 1L;
        private static final StaticOnly shared = new StaticOnly();
        private final PersistentValue value = new PersistentValue();
        private transient TransientOnly temporary = new TransientOnly();
    }

    private static class PersistentValue implements Serializable {
        private static final long serialVersionUID = 1L;
        private final String text = "persistent";
    }

    private static class StaticOnly implements Serializable {
        private static final long serialVersionUID = 1L;
    }

    private static class TransientOnly implements Serializable {
        private static final long serialVersionUID = 1L;
        private final String text = "custom";
    }

    private static class RecursiveModel implements Serializable {
        private static final long serialVersionUID = 1L;
        private RecursiveModel next;
        private PersistentValue[][] values;
        private transient TransientOnly temporary;
    }

    private static class CustomSerializedModel implements Serializable {
        private static final long serialVersionUID = 1L;
        private transient TransientOnly value = new TransientOnly();

        private void writeObject(ObjectOutputStream output) throws IOException {
            output.defaultWriteObject();
            output.writeObject(value);
        }

        private void readObject(ObjectInputStream input) throws IOException, ClassNotFoundException {
            input.defaultReadObject();
            value = (TransientOnly) input.readObject();
        }
    }
}

package com.alibaba.seckit.jdbc;

import com.alibaba.seckit.jdbc.filters.OracleFilter;
import com.alibaba.seckit.jdbc.parser.OracleUrlParser;
import com.alibaba.seckit.jdbc.parser.oracle.NVFactory;
import com.alibaba.seckit.jdbc.parser.oracle.NVPair;
import org.junit.Test;

import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

import static org.junit.Assert.*;

public class OracleTnsTest {
    private static final String PREFIX = "jdbc:oracle:thin:@";

    @Test
    public void parsesNestedListsAndRepeatedChildren() throws JdbcURLException {
        String descriptor = "(DESCRIPTION_LIST=(LOAD_BALANCE=on)"
                + "(DESCRIPTION=(ADDRESS_LIST=(ADDRESS=(PROTOCOL=TCP)(HOST=host1)(PORT=1521))"
                + "(ADDRESS=(PROTOCOL=TCPS)(HOST=host2)(PORT=5221)))"
                + "(CONNECT_DATA=(SERVICE_NAME=orcl)))"
                + "(DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST=host3))(CONNECT_DATA=(SID=test))))";
        NVPair root = parse(descriptor);
        assertEquals("DESCRIPTION_LIST", root.getName());
        assertEquals(3, root.getListSize());
        NVPair addresses = root.getListElement(1).getListElement(0);
        assertEquals(2, addresses.getListSize());
        assertEquals("host2", addresses.getListElement(1).getListElement(1).getAtom());
        assertEquals(descriptor, root.toString());
        assertEquals(descriptor, parse(root.toString()).toString());
        FilterResult result = new OracleFilter().filterPropertiesWithResult(PREFIX + descriptor);
        assertTrue(result.isSafe());
        assertEquals(PREFIX + descriptor, result.getAfter());
    }

    @Test
    public void acceptsFormattingWhitespaceWithoutChangingQuotedWhitespace() throws JdbcURLException {
        String descriptor = " \n ( DESCRIPTION = \t ( ADDRESS = ( PROTOCOL = TCP ) ( HOST = host ) )"
                + "\r\n ( CONNECT_DATA = ( SERVICE_NAME = \"  service name  \" ) ) ) \t";
        String expected = "(DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST=host))"
                + "(CONNECT_DATA=(SERVICE_NAME=\"  service name  \")))";
        assertEquals(expected, parse(descriptor).toString());
        OracleUrlParser parser = new OracleUrlParser(PREFIX + descriptor);
        parser.parse();
        assertEquals("DESCRIPTION", parser.getNvPair().getName());
        assertEquals(PREFIX + expected, parser.toString());
    }

    @Test
    public void preservesQuotedDelimitersEscapesAndUnicode() throws JdbcURLException {
        String descriptor = "(CONNECT_DATA=(SERVICE_NAME=\"svc (x)=y,#' \\\"quoted\\\" \\\\ 中文\")"
                + "(SID='single \\'quote\\' \"double\"'))";
        NVPair root = parse(descriptor);
        assertEquals("svc (x)=y,#' \"quoted\" \\ 中文", root.getListElement(0).getAtom());
        assertEquals("single 'quote' \"double\"", root.getListElement(1).getAtom());
        assertEquals(descriptor, root.toString());
        NVPair reparsed = parse(root.toString());
        assertEquals(2, reparsed.getListSize());
        assertEquals(root.getListElement(0).getAtom(), reparsed.getListElement(0).getAtom());
        assertEquals(root.getListElement(1).getAtom(), reparsed.getListElement(1).getAtom());
    }

    @Test
    public void rejectsMalformedDescriptors() throws JdbcURLException {
        String[] malformed = {
                null, "", " \t", "()", "(=value)", "(HOST)", "HOST=value", "(HOST=value",
                "(HOST=value))", "(HOST=value)garbage", "(HOST=value)(PORT=1521)",
                "(HOST=value)?foo=bar", "(DESCRIPTION=(HOST=a)trailing)",
                "(DESCRIPTION=value(HOST=a))", "(DESCRIPTION=(HOST=a), (PORT=1521))",
                "(DESCRIPTION=((HOST=a)))", "(HO ST=value)", "(HOST=a b)", "(HOST=a=b)",
                "(HOST=\"unfinished)", "(HOST='unfinished)", "(HOST=\"a\"junk)",
                "(HOST=\"a\"\"b\")", "(HOST='a'\"b\")", "(HOST=a\"b\")",
                "(HOST=\"a\"(PORT=1))", "(HOST=a#comment)", "(HOST=a\\b)",
                "(HOST=\"bad\\x\")", "(HOST=\"unfinished\\)", "(HOST=bad\u0000value)",
                "(HOST=bad\u007fvalue)", "(HOST=bad\u0085value)", "(HOST=bad\ud800value)",
                "(HOST=bad\udc00value)", "(HOST=\"bad\nvalue\")", "(HOST=a\u00a0b)"
        };
        for (String descriptor : malformed) {
            assertInvalid(descriptor);
        }
    }

    @Test
    public void rejectsMalformedJdbcDescriptors() throws JdbcURLException {
        String[] malformed = {
                "(DESCRIPTION=(HOST=a))suffix", "(DESCRIPTION=(HOST=a)))(PORT=1)",
                "(DESCRIPTION=atom(HOST=a))", "(DESCRIPTION=(HOST=\"unterminated))"
        };
        for (String descriptor : malformed) {
            try {
                new OracleFilter().filterPropertiesWithResult(PREFIX + descriptor);
                fail("Malformed JDBC descriptor was accepted");
            } catch (JdbcURLUnsafeException expected) {
                assertNotNull(expected.getMessage());
            }
        }
    }

    @Test
    public void boundsNestingBeforeStackOverflow() throws JdbcURLException {
        String deepest = nestedDescriptor(64);
        assertEquals(deepest, parse(deepest).toString());
        assertEquals(PREFIX + deepest, new OracleFilter().filterProperties(PREFIX + deepest));
        assertInvalid(nestedDescriptor(65));
        assertInvalid(nestedDescriptor(1000));
    }

    @Test
    public void boundsInputLength() throws JdbcURLException {
        StringBuilder descriptor = new StringBuilder("(HOST=");
        for (int index = 0; index < 65529; index++) {
            descriptor.append('a');
        }
        descriptor.append(')');
        assertEquals(65536, descriptor.length());
        assertEquals(descriptor.toString(), parse(descriptor.toString()).toString());
        assertInvalid(descriptor + " ");
    }

    @Test
    public void filtersListEmptyAndDisallowedProtocolsWithoutRemovingNeighbors() throws JdbcURLException {
        String descriptor = "(DESCRIPTION=(ADDRESS=(PROTOCOL=(HOST=hidden))"
                + "(HOST=host1)(PROTOCOL=)(PROTOCOL=LDAP)(PORT=1521)"
                + "(PROTOCOL=TCP)(PROTOCOL='tCpS')(PROTOCOL=\"tcp\")(FOO=bar)(BAR=baz)))";
        String expected = "(DESCRIPTION=(ADDRESS=(HOST=host1)(PORT=1521)"
                + "(PROTOCOL=TCP)(PROTOCOL='tCpS')(PROTOCOL=\"tcp\")))";
        OracleFilter filter = new OracleFilter();
        FilterResult result = filter.filterPropertiesWithResult(PREFIX + descriptor);
        assertFalse(result.isSafe());
        assertTrue(result.getDeleted().containsKey("PROTOCOL"));
        assertTrue(result.getDeleted().containsKey("FOO"));
        assertTrue(result.getDeleted().containsKey("BAR"));
        assertEquals(PREFIX + expected, result.getAfter());
        assertEquals(expected, parse(result.getAfter().substring(PREFIX.length())).toString());
        assertTrue(filter.filterPropertiesWithResult(result.getAfter()).isSafe());
    }

    @Test
    public void removesAChildOnlyOnceWhenBothChecksRejectIt() throws JdbcURLException {
        OracleFilter filter = new OracleFilter();
        Set<String> accepted = new HashSet<>(filter.getAcceptedPairNames());
        accepted.remove("PROTOCOL");
        filter.setAcceptedPairNames(accepted);
        FilterResult result = filter.filterPropertiesWithResult(PREFIX
                + "(DESCRIPTION=(ADDRESS=(PROTOCOL=(HOST=hidden))(HOST=host1)"
                + "(PROTOCOL=LDAP)(PORT=1521)))");
        assertFalse(result.isSafe());
        assertEquals(PREFIX + "(DESCRIPTION=(ADDRESS=(HOST=host1)(PORT=1521)))", result.getAfter());
    }

    @Test
    public void preservesQuotedAtomsAfterFiltering() throws JdbcURLException {
        String service = "\"svc)(PROTOCOL=LDAP) (x)=y # \\\"quoted\\\"\"";
        String descriptor = "(DESCRIPTION=(ADDRESS=(PROTOCOL=\"TCPS\")(HOST='host name'))"
                + "(CONNECT_DATA=(FOO=bar)(SERVICE_NAME=" + service + ")(SID=''))(FOO=baz))";
        String expected = "(DESCRIPTION=(ADDRESS=(PROTOCOL=\"TCPS\")(HOST='host name'))"
                + "(CONNECT_DATA=(SERVICE_NAME=" + service + ")(SID='')))";
        OracleFilter filter = new OracleFilter();
        FilterResult result = filter.filterPropertiesWithResult(PREFIX + descriptor);
        assertFalse(result.isSafe());
        assertEquals(PREFIX + expected, result.getAfter());
        NVPair data = parse(expected).getListElement(1);
        assertEquals(2, data.getListSize());
        assertEquals("svc)(PROTOCOL=LDAP) (x)=y # \"quoted\"", data.getListElement(0).getAtom());
        assertEquals("", data.getListElement(1).getAtom());
        assertEquals(result.getAfter(), filter.filterProperties(result.getAfter()));
    }

    @Test
    public void serializesParentsWhoseChildrenWereAllRemoved() throws JdbcURLException {
        OracleFilter filter = new OracleFilter();
        FilterResult result = filter.filterPropertiesWithResult(PREFIX
                + "(DESCRIPTION=(ADDRESS=(PROTOCOL=(HOST=hidden))(FOO=bar))(FOO=baz))");
        assertFalse(result.isSafe());
        assertEquals(PREFIX + "(DESCRIPTION=(ADDRESS=))", result.getAfter());
        assertEquals("(DESCRIPTION=(ADDRESS=))", parse("(DESCRIPTION=(ADDRESS=))").toString());
        assertEquals(result.getAfter(), filter.filterProperties(result.getAfter()));
        result = filter.filterPropertiesWithResult(PREFIX + "(DESCRIPTION=(FOO=bar))");
        assertEquals(PREFIX + "(DESCRIPTION=)", result.getAfter());
        assertEquals(result.getAfter(), filter.filterProperties(result.getAfter()));
    }

    @Test
    public void appliesTheSameChecksToTheRoot() throws JdbcURLException {
        OracleFilter filter = new OracleFilter();
        String[] rejected = {"(FOO=(DESCRIPTION=(HOST=host)))", "(PROTOCOL=(HOST=host))", "(PROTOCOL=LDAP)"};
        for (String descriptor : rejected) {
            FilterResult result = filter.filterPropertiesWithResult(PREFIX + descriptor);
            assertFalse(result.isSafe());
            assertEquals(PREFIX, result.getAfter());
            assertEquals(1, result.getDeleted().size());
        }
        assertEquals(PREFIX + "(PROTOCOL=TCP)", filter.filterProperties(PREFIX + "(PROTOCOL=TCP)"));
    }

    @Test
    public void checksNamesIndependentlyOfTheDefaultLocale() throws JdbcURLException {
        Locale previous = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("tr", "TR"));
            String descriptor = "(description=(address=(protocol=tcps)(host=host))"
                    + "(connect_data=(sid=test)))";
            FilterResult result = new OracleFilter().filterPropertiesWithResult(PREFIX + descriptor);
            assertTrue(result.isSafe());
            assertEquals(PREFIX + descriptor, result.getAfter());
        } finally {
            Locale.setDefault(previous);
        }
    }

    private NVPair parse(String descriptor) throws JdbcURLException {
        return new NVFactory().createNVPair(descriptor);
    }

    private void assertInvalid(String descriptor) throws JdbcURLException {
        try {
            parse(descriptor);
            fail("Malformed descriptor was accepted");
        } catch (JdbcURLUnsafeException expected) {
            assertNotNull(expected.getMessage());
        }
    }

    private String nestedDescriptor(int depth) {
        StringBuilder descriptor = new StringBuilder();
        for (int index = 1; index < depth; index++) {
            descriptor.append("(DESCRIPTION=");
        }
        descriptor.append("(HOST=host)");
        for (int index = 1; index < depth; index++) {
            descriptor.append(')');
        }
        return descriptor.toString();
    }
